<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{Message}from'@arco-design/web-vue';import{adminApi,type PublicSettings}from'@/api/admin';import{PublicApiError}from'@/api/client'
const form=reactive<PublicSettings>({site:{name:'GIM',version:'v1',notice:'',registrationEnabled:true},openLogin:{enabled:false}}),loading=ref(false),saving=ref(false);function report(e:unknown){Message.error(e instanceof PublicApiError?e.message:'请求失败')};async function load(){loading.value=true;try{Object.assign(form,await adminApi.settings())}catch(e){report(e)}finally{loading.value=false}};async function save(){saving.value=true;try{Object.assign(form,await adminApi.updateSettings(form));Message.success('公开业务设置已更新')}catch(e){report(e)}finally{saving.value=false}};onMounted(load)
</script>
<template><section class="page-stack"><a-alert type="warning">此处仅保存公开业务设置；Kafka、数据库、Redis、JWT 与第三方 Secret 始终来自部署配置。</a-alert><a-card :bordered="false" title="公开业务设置" :loading="loading"><a-form :model="form" layout="vertical" class="settings-form"><a-form-item label="站点名称"><a-input v-model="form.site.name" :max-length="64"/></a-form-item><a-form-item label="版本标识"><a-input v-model="form.site.version" :max-length="32"/></a-form-item><a-form-item label="站点公告"><a-textarea v-model="form.site.notice" :max-length="500" show-word-limit/></a-form-item><a-form-item label="开放注册"><a-switch v-model="form.site.registrationEnabled"/></a-form-item><a-form-item label="开放登录入口"><a-switch v-model="form.openLogin.enabled"/><span class="field-note">仅控制入口可见性，不在 Settings 中存 OAuth Key/Secret。</span></a-form-item><a-button type="primary" :loading="saving" @click="save">保存设置</a-button></a-form></a-card></section></template>
